'use strict';

// MAIN //

/**
* Tests if an object's own property is enumerable.
*
* ## Notes
*
* -   Enumerable own symbol properties are not detected (`Object.keys` cannot see symbols).
*
* @private
* @param {*} property - property to test
* @returns {boolean} boolean indicating if an object property is enumerable
*
* @example
* var beep = {
*     'boop': true
* };
*
* var bool = isEnumerableProperty.call( beep, 'boop' );
* // returns true
*
* @example
* var beep = {
*     'boop': true
* };
*
* var bool = isEnumerableProperty.call( beep, 'hasOwnProperty' );
* // returns false
*/
function isEnumerableProperty( property ) {
	var keys;
	var prop;
	var i;

	if ( this === null || this === void 0 ) {
		return false;
	}
	if ( typeof property === 'symbol' ) {
		return false;
	}
	keys = Object.keys( Object( this ) );
	prop = '' + property;
	for ( i = 0; i < keys.length; i++ ) {
		if ( keys[ i ] === prop ) {
			return true;
		}
	}
	return false;
}


// EXPORTS //

module.exports = isEnumerableProperty;
